CREATE FUNCTION public.editar_socio_datos(p_id uuid,p_nombre text,p_email text,p_telefono text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e text:=lower(trim(p_email)); old_e text; BEGIN IF NOT public.has_club_role('directiva') THEN RAISE EXCEPTION 'No autorizado'; END IF; IF e IS NULL OR e !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN RAISE EXCEPTION 'Email obligatorio'; END IF; IF EXISTS(SELECT 1 FROM public.socios WHERE lower(email)=e AND id<>p_id) THEN RAISE EXCEPTION 'Este email ya tiene socio'; END IF; SELECT email INTO old_e FROM public.socios WHERE id=p_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Socio no disponible'; END IF; UPDATE public.socios SET nombre=trim(p_nombre),email=e,telefono=p_telefono WHERE id=p_id; UPDATE public.usuario_roles SET email=e,nombre=trim(p_nombre),user_id=(SELECT id FROM auth.users WHERE lower(email)=e AND email_confirmed_at IS NOT NULL LIMIT 1) WHERE socio_id=p_id AND rol='socia'; END $$;
REVOKE ALL ON FUNCTION public.editar_socio_datos(uuid,text,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.editar_socio_datos(uuid,text,text,text) TO authenticated;
CREATE FUNCTION public.validar_alta_pagada() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.pagos WHERE socio_id=NEW.id AND temporada=NEW.temporada) THEN RAISE EXCEPTION 'El alta requiere un pago registrado'; END IF; RETURN NEW; END $$;
CREATE CONSTRAINT TRIGGER socios_pago_obligatorio AFTER INSERT ON public.socios DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.validar_alta_pagada();
CREATE FUNCTION public.validar_cuota() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.cuota_socio IS NOT NULL AND (NEW.cuota_socio<=0 OR NEW.cuota_socio='NaN'::numeric) THEN RAISE EXCEPTION 'Cuota no válida'; END IF; RETURN NEW; END $$;
CREATE TRIGGER ajustes_cuota BEFORE INSERT OR UPDATE ON public.ajustes_club FOR EACH ROW EXECUTE FUNCTION public.validar_cuota();